import axios from 'axios';
import * as cheerio from 'cheerio';
import type { ImageInfo, ScrapingResult, ScrapeOptions } from './types';

const SUPPORTED_FORMATS = ['jpg', 'jpeg', 'png', 'gif', 'webp', 'svg', 'bmp', 'ico'];
const USER_AGENT = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36';

/**
 * Scrape all images from a URL
 */
export async function scrapeImages(url: string, options: ScrapeOptions = {}): Promise<ScrapingResult> {
  const { maxImages = 50, deepScan = false, formats } = options;
  const allowedFormats = formats?.length ? formats : SUPPORTED_FORMATS;

  const images: ImageInfo[] = [];
  const errors: string[] = [];

  try {
    const normalizedUrl = normalizeUrl(url);
    const baseUrl = new URL(normalizedUrl);

    const response = await axios.get(normalizedUrl, {
      headers: {
        'User-Agent': USER_AGENT,
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
        'Accept-Language': 'en-US,en;q=0.5',
        'Accept-Encoding': 'gzip, deflate',
        'Connection': 'keep-alive',
        'Upgrade-Insecure-Requests': '1',
      },
      timeout: 10000,
      responseType: 'arraybuffer'
    });

    const contentType = response.headers['content-type'] || '';
    const responseData = response.data.toString('utf-8');

    // Check if URL is a direct image link
    if (contentType.startsWith('image/')) {
      const filename = generateFilename(normalizedUrl);
      const format = getImageFormat(normalizedUrl);

      return {
        images: [{
          url: normalizedUrl,
          filename,
          size: response.data.length,
          format,
        }],
        totalImages: 1,
        errors: []
      };
    }

    const $ = cheerio.load(responseData);

    // Extract from <img> tags
    $('img').each((_, element) => {
      if (images.length >= maxImages) return false;

      const src = $(element).attr('src') || $(element).attr('data-src') || $(element).attr('data-lazy-src');
      if (!src) return;

      try {
        const imageUrl = resolveImageUrl(src, baseUrl);
        if (imageUrl && isValidImageUrl(imageUrl, allowedFormats)) {
          const filename = generateFilename(imageUrl);
          const format = getImageFormat(imageUrl);

          if (!images.some(img => img.url === imageUrl)) {
            images.push({
              url: imageUrl,
              filename,
              size: 0,
              format,
            });
          }
        }
      } catch {
        errors.push(`Failed to process image: ${src}`);
      }
    });

    // Extract CSS background images (inline styles)
    $('[style*="background"]').each((_, element) => {
      if (images.length >= maxImages) return false;

      const style = $(element).attr('style');
      if (!style) return;

      const backgroundMatch = style.match(/background(?:-image)?\s*:\s*url\(['"]?([^'"]+)['"]?\)/i);
      if (backgroundMatch) {
        try {
          const imageUrl = resolveImageUrl(backgroundMatch[1], baseUrl);
          if (imageUrl && isValidImageUrl(imageUrl, allowedFormats)) {
            const filename = generateFilename(imageUrl);
            const format = getImageFormat(imageUrl);

            if (!images.some(img => img.url === imageUrl)) {
              images.push({
                url: imageUrl,
                filename,
                size: 0,
                format,
              });
            }
          }
        } catch {
          errors.push(`Failed to process background image: ${backgroundMatch[1]}`);
        }
      }
    });

    // Deep scan: parse external CSS files
    if (deepScan) {
      const cssLinks: string[] = [];
      $('link[rel="stylesheet"]').each((_, el) => {
        const href = $(el).attr('href');
        if (href) cssLinks.push(href);
      });

      const cssToScan = cssLinks.slice(0, 5);

      for (const cssLink of cssToScan) {
        if (images.length >= maxImages) break;

        try {
          const cssUrl = resolveImageUrl(cssLink, baseUrl);
          const cssResponse = await axios.get(cssUrl, {
            headers: { 'User-Agent': USER_AGENT },
            timeout: 5000
          });

          const cssContent = cssResponse.data;
          const urlMatches = cssContent.matchAll(/url\(['"]?([^'"]+)['"]?\)/gi);

          for (const match of urlMatches) {
            if (images.length >= maxImages) break;
            const potentialUrl = match[1];

            if (potentialUrl.startsWith('data:')) continue;

            try {
              const cssUrlObj = new URL(cssUrl);
              const imageUrl = resolveImageUrl(potentialUrl, cssUrlObj);

              if (imageUrl && isValidImageUrl(imageUrl, allowedFormats)) {
                const filename = generateFilename(imageUrl);
                const format = getImageFormat(imageUrl);

                if (!images.some(img => img.url === imageUrl)) {
                  images.push({
                    url: imageUrl,
                    filename,
                    size: 0,
                    format,
                  });
                }
              }
            } catch {
              // ignore invalid urls in css
            }
          }
        } catch (err) {
          errors.push(`Failed to scan CSS file ${cssLink}: ${err instanceof Error ? err.message : 'Unknown error'}`);
        }
      }
    }

  } catch (error) {
    errors.push(`Failed to fetch webpage: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }

  return {
    images: images.slice(0, maxImages),
    totalImages: images.length,
    errors,
  };
}

function normalizeUrl(url: string): string {
  if (!url.startsWith('http://') && !url.startsWith('https://')) {
    return `https://${url}`;
  }
  return url;
}

function resolveImageUrl(src: string, baseUrl: URL): string {
  if (src.startsWith('http://') || src.startsWith('https://')) {
    return src;
  }

  if (src.startsWith('//')) {
    return `${baseUrl.protocol}${src}`;
  }

  if (src.startsWith('/')) {
    return `${baseUrl.protocol}//${baseUrl.host}${src}`;
  }

  try {
    return new URL(src, baseUrl.href).href;
  } catch {
    return `${baseUrl.protocol}//${baseUrl.host}/${src.replace(/^\//, '')}`;
  }
}

function isValidImageUrl(url: string, allowedFormats: string[]): boolean {
  try {
    const urlObj = new URL(url);
    const extension = urlObj.pathname.split('.').pop()?.toLowerCase();
    return extension ? allowedFormats.includes(extension) : false;
  } catch {
    return false;
  }
}

function generateFilename(url: string): string {
  try {
    const urlObj = new URL(url);
    const pathname = urlObj.pathname;
    const filename = pathname.split('/').pop() || 'image';
    const extension = filename.split('.').pop()?.toLowerCase() || 'jpg';

    const cleanName = filename.replace(/[^a-zA-Z0-9.-]/g, '_');
    return cleanName.includes('.') ? cleanName : `${cleanName}.${extension}`;
  } catch {
    return `image_${Date.now()}.jpg`;
  }
}

function getImageFormat(url: string): string {
  try {
    const urlObj = new URL(url);
    const extension = urlObj.pathname.split('.').pop()?.toLowerCase() || 'jpg';
    return SUPPORTED_FORMATS.includes(extension) ? extension : 'jpg';
  } catch {
    return 'jpg';
  }
}
