import * as fs from 'fs';
import * as path from 'path';
import { scrapeImages } from './scraper';
import { createZipFromImages, generateZipFilename } from './zip';
import type { DownloadOptions, DownloadResult, ScrapeOptions, ScrapingResult } from './types';

// Re-export types
export type {
  ImageInfo,
  DownloadProgress,
  ScrapingResult,
  ScrapeOptions,
  DownloadOptions,
  DownloadResult,
} from './types';

// Re-export scraper
export { scrapeImages } from './scraper';

/**
 * Download all images from a URL and save as a ZIP file
 *
 * @example
 * ```ts
 * import { downloadImages } from 'imgminer';
 *
 * // Download to current directory
 * const result = await downloadImages('https://example.com');
 * console.log(`Downloaded ${result.downloadedCount} images to ${result.zipPath}`);
 *
 * // With options
 * const result = await downloadImages('https://example.com', {
 *   maxImages: 100,
 *   deepScan: true,
 *   outputDir: './downloads',
 *   onProgress: (p) => console.log(`${p.percentage}% - ${p.current}`)
 * });
 * ```
 */
export async function downloadImages(url: string, options: DownloadOptions = {}): Promise<DownloadResult> {
  const { outputDir, filename, onProgress, ...scrapeOptions } = options;

  // Scrape images from URL
  const scrapeResult = await scrapeImages(url, scrapeOptions);

  if (scrapeResult.images.length === 0) {
    return {
      zipPath: '',
      totalSize: 0,
      downloadedCount: 0,
      images: [],
      errors: scrapeResult.errors.length > 0
        ? scrapeResult.errors
        : ['No images found on the page'],
    };
  }

  // Create ZIP from images
  const { zipBuffer, totalSize, downloadedCount } = await createZipFromImages(
    scrapeResult.images,
    onProgress
  );

  // Generate filename
  const zipFilename = filename || generateZipFilename(url);

  // Save to file or return buffer
  let zipPath = '';
  let resultBuffer: Buffer | undefined;

  if (outputDir) {
    zipPath = path.join(outputDir, zipFilename);
    await fs.promises.mkdir(outputDir, { recursive: true });
    await fs.promises.writeFile(zipPath, zipBuffer);
  } else {
    zipPath = zipFilename;
    resultBuffer = zipBuffer;
  }

  return {
    zipPath,
    zipBuffer: resultBuffer,
    totalSize,
    downloadedCount,
    images: scrapeResult.images,
    errors: scrapeResult.errors,
  };
}

/**
 * Get images from a URL without downloading (just scrape URLs)
 *
 * @example
 * ```ts
 * import { getImages } from 'imgminer';
 *
 * const result = await getImages('https://example.com');
 * console.log(`Found ${result.totalImages} images`);
 * result.images.forEach(img => console.log(img.url));
 * ```
 */
export async function getImages(url: string, options: ScrapeOptions = {}): Promise<ScrapingResult> {
  return scrapeImages(url, options);
}

// Default export for convenience
export default {
  downloadImages,
  getImages,
  scrapeImages,
};
