import axios from 'axios';
import JSZip from 'jszip';
import sharp from 'sharp';
import type { ImageInfo, DownloadProgress } from './types';

const USER_AGENT = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36';
const MAX_FILE_SIZE = 50 * 1024 * 1024; // 50MB limit per file
const TIMEOUT = 10000; // 10 seconds

export async function createZipFromImages(
  images: ImageInfo[],
  onProgress?: (progress: DownloadProgress) => void
): Promise<{ zipBuffer: Buffer; totalSize: number; downloadedCount: number }> {
  const zip = new JSZip();
  let totalSize = 0;
  let downloadedCount = 0;

  for (let i = 0; i < images.length; i++) {
    const image = images[i];

    try {
      if (onProgress) {
        onProgress({
          total: images.length,
          downloaded: downloadedCount,
          current: image.filename,
          percentage: Math.round((i / images.length) * 100),
        });
      }

      const imageBuffer = await downloadImage(image.url);
      if (!imageBuffer) {
        continue;
      }

      const processedBuffer = await processImage(imageBuffer, image.format);

      zip.file(image.filename, processedBuffer);

      totalSize += processedBuffer.length;
      downloadedCount++;

    } catch (error) {
      // Continue with next image on error
    }
  }

  const zipBuffer = await zip.generateAsync({
    type: 'nodebuffer',
    compression: 'DEFLATE',
    compressionOptions: {
      level: 6,
    },
  });

  return {
    zipBuffer,
    totalSize,
    downloadedCount,
  };
}

async function downloadImage(url: string): Promise<Buffer | null> {
  try {
    const response = await axios.get(url, {
      responseType: 'arraybuffer',
      headers: {
        'User-Agent': USER_AGENT,
        'Accept': 'image/webp,image/apng,image/*,*/*;q=0.8',
        'Accept-Language': 'en-US,en;q=0.5',
        'Accept-Encoding': 'gzip, deflate',
        'Connection': 'keep-alive',
      },
      timeout: TIMEOUT,
      maxContentLength: MAX_FILE_SIZE,
    });

    if (response.status !== 200) {
      return null;
    }

    return Buffer.from(response.data);
  } catch {
    return null;
  }
}

async function processImage(buffer: Buffer, format: string): Promise<Buffer> {
  try {
    let sharpInstance = sharp(buffer);

    const metadata = await sharpInstance.metadata();

    if (metadata.width && metadata.width > 2048) {
      sharpInstance = sharpInstance.resize(2048, null, {
        withoutEnlargement: true,
        fit: 'inside',
      });
    }
    if (metadata.height && metadata.height > 2048) {
      sharpInstance = sharpInstance.resize(null, 2048, {
        withoutEnlargement: true,
        fit: 'inside',
      });
    }

    switch (format.toLowerCase()) {
      case 'jpg':
      case 'jpeg':
        return await sharpInstance.jpeg({ quality: 85, progressive: true }).toBuffer();
      case 'png':
        return await sharpInstance.png({ compressionLevel: 6 }).toBuffer();
      case 'webp':
        return await sharpInstance.webp({ quality: 85 }).toBuffer();
      case 'gif':
        return await sharpInstance.gif().toBuffer();
      default:
        return await sharpInstance.jpeg({ quality: 85, progressive: true }).toBuffer();
    }
  } catch {
    return buffer;
  }
}

export function generateZipFilename(baseUrl: string): string {
  try {
    const url = new URL(baseUrl);
    const hostname = url.hostname.replace(/[^a-zA-Z0-9]/g, '_');
    const timestamp = new Date().toISOString().slice(0, 19).replace(/:/g, '-');
    return `${hostname}_images_${timestamp}.zip`;
  } catch {
    const timestamp = new Date().toISOString().slice(0, 19).replace(/:/g, '-');
    return `images_${timestamp}.zip`;
  }
}
